import{_ as t,c as n,o as i,ae as o}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"AI Content Manager User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Assistant/launchpad.md","filePath":"Assistant/launchpad.md"}'),a={name:"Assistant/launchpad.md"};function l(s,e,r,c,d,h){return i(),n("div",null,e[0]||(e[0]=[o('<h1 id="ai-content-manager-user-guide" tabindex="-1">AI Content Manager User Guide <a class="header-anchor" href="#ai-content-manager-user-guide" aria-label="Permalink to &quot;AI Content Manager User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#ai-content-manager-user-guide">AI Content Manager User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-the-content-manager">Accessing the Content Manager</a></li><li><a href="#content-manager-interface">Content Manager Interface</a></li><li><a href="#content-selection">Content Selection</a><ul><li><a href="#selected-content-view">Selected Content View</a></li><li><a href="#managing-selected-content">Managing Selected Content</a></li></ul></li><li><a href="#knowledge-base-selection">Knowledge Base Selection</a><ul><li><a href="#browsing-knowledge-bases">Browsing Knowledge Bases</a></li><li><a href="#selecting-knowledge-bases">Selecting Knowledge Bases</a></li></ul></li><li><a href="#individual-content-selection">Individual Content Selection</a><ul><li><a href="#browsing-content-items">Browsing Content Items</a></li><li><a href="#selecting-specific-content-items">Selecting Specific Content Items</a></li></ul></li><li><a href="#personal-content">Personal Content</a><ul><li><a href="#uploading-files">Uploading Files</a></li><li><a href="#content-categories">Content Categories</a></li></ul></li><li><a href="#search-functionality">Search Functionality</a></li><li><a href="#creating-content-chats">Creating Content Chats</a></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The AI Content Manager allows you to select specific knowledge sources for your AI conversations. This sidebar interface enables you to browse, search, and select from available knowledge bases and content items, giving you precise control over what information the AI can access during your conversation. By providing focused knowledge sources, you can get more targeted and relevant responses for your specific needs.</p><h2 id="accessing-the-content-manager" tabindex="-1">Accessing the Content Manager <a class="header-anchor" href="#accessing-the-content-manager" aria-label="Permalink to &quot;Accessing the Content Manager&quot;">​</a></h2><p>The Content Manager appears as a sidebar panel within the AI Assistant interface:</p><ol><li>Click the content/document icon in the main menu of the AI Assistant</li><li>The Content Manager sidebar opens on the right side of the interface</li><li>From here, you can browse, search, and select content for your conversation</li></ol><h2 id="content-manager-interface" tabindex="-1">Content Manager Interface <a class="header-anchor" href="#content-manager-interface" aria-label="Permalink to &quot;Content Manager Interface&quot;">​</a></h2><p>The Content Manager consists of four main sections:</p><ol><li><strong>Header</strong>: Contains the &quot;New Content Chat&quot; button and search bar</li><li><strong>Selected Content</strong>: Displays currently selected items as chips</li><li><strong>Knowledge Bases</strong>: Accordion panel for browsing and selecting knowledge repositories</li><li><strong>Assigned Content</strong>: Accordion panel for selecting specific content items</li><li><strong>My Content</strong>: Accordion panel for personal file uploads and categories</li></ol><h2 id="content-selection" tabindex="-1">Content Selection <a class="header-anchor" href="#content-selection" aria-label="Permalink to &quot;Content Selection&quot;">​</a></h2><h3 id="selected-content-view" tabindex="-1">Selected Content View <a class="header-anchor" href="#selected-content-view" aria-label="Permalink to &quot;Selected Content View&quot;">​</a></h3><p>The top section displays all currently selected content:</p><ol><li>Each selected item appears as a colored chip: <ul><li>Knowledge Base items: Blue/primary color background</li><li>Individual content items: White/neutral background</li></ul></li><li>Chips display the name of each selected knowledge base or content item</li><li>Empty state shows &quot;empty&quot; when no content is selected</li><li>This area scrolls if many items are selected</li></ol><h3 id="managing-selected-content" tabindex="-1">Managing Selected Content <a class="header-anchor" href="#managing-selected-content" aria-label="Permalink to &quot;Managing Selected Content&quot;">​</a></h3><p>To manage your selected content:</p><ol><li><strong>Removing Individual Items</strong>: Click the X on any chip to remove that item</li><li><strong>Clearing All Selections</strong>: Click the &quot;clear&quot; badge next to &quot;Selected Content&quot; heading</li><li><strong>Adding New Items</strong>: Use the Knowledge Bases or Assigned Content panels</li></ol><p>Changes to selected content are applied immediately to the conversation context.</p><h2 id="knowledge-base-selection" tabindex="-1">Knowledge Base Selection <a class="header-anchor" href="#knowledge-base-selection" aria-label="Permalink to &quot;Knowledge Base Selection&quot;">​</a></h2><h3 id="browsing-knowledge-bases" tabindex="-1">Browsing Knowledge Bases <a class="header-anchor" href="#browsing-knowledge-bases" aria-label="Permalink to &quot;Browsing Knowledge Bases&quot;">​</a></h3><p>To browse available knowledge bases:</p><ol><li>Click the &quot;Knowledge Bases&quot; accordion panel to expand it</li><li>View the list of available knowledge bases</li><li>Each knowledge base appears with: <ul><li>Name and description</li><li>Checkbox for selection</li><li>Visual indicator of content volume</li></ul></li><li>Use the search box at the top to filter knowledge bases by name or description</li></ol><h3 id="selecting-knowledge-bases" tabindex="-1">Selecting Knowledge Bases <a class="header-anchor" href="#selecting-knowledge-bases" aria-label="Permalink to &quot;Selecting Knowledge Bases&quot;">​</a></h3><p>To select knowledge bases for your conversation:</p><ol><li>Click the checkbox next to each knowledge base you want to include</li><li>Selected knowledge bases appear in the Selected Content area at the top</li><li>Selecting a knowledge base includes all its content in the conversation context</li><li>You can combine multiple knowledge bases for broader coverage</li></ol><h2 id="individual-content-selection" tabindex="-1">Individual Content Selection <a class="header-anchor" href="#individual-content-selection" aria-label="Permalink to &quot;Individual Content Selection&quot;">​</a></h2><h3 id="browsing-content-items" tabindex="-1">Browsing Content Items <a class="header-anchor" href="#browsing-content-items" aria-label="Permalink to &quot;Browsing Content Items&quot;">​</a></h3><p>To browse individual content items:</p><ol><li>Click the &quot;Assigned Content&quot; accordion panel to expand it</li><li>View the list of available content items across all knowledge bases</li><li>Each content item appears with: <ul><li>Name/title</li><li>File type icon</li><li>Parent knowledge base</li><li>Additional metadata</li></ul></li><li>Use the search box to find specific content by name, type, or topic</li></ol><h3 id="selecting-specific-content-items" tabindex="-1">Selecting Specific Content Items <a class="header-anchor" href="#selecting-specific-content-items" aria-label="Permalink to &quot;Selecting Specific Content Items&quot;">​</a></h3><p>For more granular control over conversation context:</p><ol><li>Click the checkbox next to each content item you want to include</li><li>Selected content items appear in the Selected Content area at the top</li><li>This approach is more precise than selecting entire knowledge bases</li><li>Ideal when you need very specific information sources</li></ol><h2 id="personal-content" tabindex="-1">Personal Content <a class="header-anchor" href="#personal-content" aria-label="Permalink to &quot;Personal Content&quot;">​</a></h2><h3 id="uploading-files" tabindex="-1">Uploading Files <a class="header-anchor" href="#uploading-files" aria-label="Permalink to &quot;Uploading Files&quot;">​</a></h3><p>To use your own files in a conversation:</p><ol><li>Expand the &quot;My Content&quot; accordion panel</li><li>Click &quot;Upload File&quot; to open your device&#39;s file browser</li><li>Select a file to upload (image formats supported)</li><li>Size limit: 1MB per file</li><li>Uploaded files appear under selected categories</li></ol><h3 id="content-categories" tabindex="-1">Content Categories <a class="header-anchor" href="#content-categories" aria-label="Permalink to &quot;Content Categories&quot;">​</a></h3><p>Organize your personal content with categories:</p><ol><li>In the My Content panel, view available categories: <ul><li>Marketing</li><li>Production</li><li>Research</li></ul></li><li>Check the categories you want to apply to your content</li><li>Files can belong to multiple categories for better organization</li></ol><h2 id="search-functionality" tabindex="-1">Search Functionality <a class="header-anchor" href="#search-functionality" aria-label="Permalink to &quot;Search Functionality&quot;">​</a></h2><p>The search feature helps you quickly find content:</p><ol><li>Type in the search box at the top of the Content Manager</li><li>Search applies to both knowledge bases and content items simultaneously</li><li>Results update in real-time as you type</li><li>Search matches: <ul><li>Knowledge base names and descriptions</li><li>Content titles and metadata</li><li>Tags and topics</li></ul></li><li>Clear the search box to return to the full list</li></ol><h2 id="creating-content-chats" tabindex="-1">Creating Content Chats <a class="header-anchor" href="#creating-content-chats" aria-label="Permalink to &quot;Creating Content Chats&quot;">​</a></h2><p>To start a new conversation with your selected content:</p><ol><li>Click the &quot;New Content Chat&quot; button at the top of the Content Manager</li><li>A new conversation starts with the currently selected content items</li><li>The AI will only use knowledge from your selected sources</li><li>This creates a focused conversation context for targeted answers</li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective content selection:</p><ol><li><p><strong>Targeted Selection</strong>:</p><ul><li>Choose only relevant knowledge bases and content for your current topic</li><li>Too many sources can dilute relevance</li><li>Too few may limit the AI&#39;s knowledge</li></ul></li><li><p><strong>Knowledge Base vs. Individual Content</strong>:</p><ul><li>Use knowledge bases for broad topics</li><li>Select individual content for specific questions</li><li>Mix approaches when needed for optimal results</li></ul></li><li><p><strong>Search Strategies</strong>:</p><ul><li>Use specific terms to narrow results</li><li>Try different search terms for better matches</li><li>Clear search between different content needs</li></ul></li><li><p><strong>Managing Content Lists</strong>:</p><ul><li>Periodically clear all selections when changing topics</li><li>Review selected content to ensure relevance</li><li>Remove outdated or irrelevant selections</li></ul></li><li><p><strong>Content Combinations</strong>:</p><ul><li>Try different combinations for best results</li><li>Start broad, then narrow if needed</li><li>Consider combining reference documents with how-to content</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Content not appearing in search results</p><ul><li>Try different search terms</li><li>Check if content exists in the system</li><li>Verify you have permissions to access that content</li><li>Try clearing the search and browsing manually</li></ul><p><strong>Issue</strong>: Cannot select certain content</p><ul><li>Verify you have access permissions for that content</li><li>Check if the content is active and available</li><li>Try refreshing the Content Manager</li><li>Contact your administrator if permission issues persist</li></ul><p><strong>Issue</strong>: Selected content not affecting AI responses</p><ul><li>Ensure content is properly selected (appears in chips)</li><li>Try starting a new content chat</li><li>Ask questions that specifically relate to the selected content</li><li>Check if content contains information relevant to your questions</li></ul><p><strong>Issue</strong>: Knowledge bases not loading</p><ul><li>Wait a moment as knowledge bases might be loading</li><li>Try expanding/collapsing the accordion panel</li><li>Refresh the Content Manager</li><li>Check your network connection</li></ul><p><strong>Issue</strong>: File upload failures</p><ul><li>Verify file is under the size limit (1MB)</li><li>Check that file format is supported (images)</li><li>Ensure you have upload permissions</li><li>Try a different browser if issues persist</li></ul><p><strong>Issue</strong>: Content chips disappear unexpectedly</p><ul><li>Another user or process might have modified permissions</li><li>The system might have refreshed content listings</li><li>Try reselecting the content items</li><li>If persistent, check with your administrator</li></ul><hr><p>For additional assistance with the Content Manager, please contact your system administrator or refer to the platform documentation.</p>',64)]))}const p=t(a,[["render",l]]);export{g as __pageData,p as default};
